source2='''def transform(grid):
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    color = next(v for row in grid for v in row if v != bg)
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    def groups(points):
        if not points: return []
        result=[]; group=[points[0]]
        for p in points[1:]:
            if p-group[-1] <= 7: group.append(p)
            else: result.append(group); group=[p]
        result.append(group)
        return [g for g in result if len(g)>=3]
    hgroups=[]
    vgroups=[]
    for r in range(h):
        for g in groups([c for c,v in enumerate(grid[r]) if v==color]):
            hgroups.append((r,g[0],g[-1]))
            for a,b in zip(g,g[1:]):
                for c in range(a+1,b):
                    if grid[r][c]==bg: out[r][c]=2
    for c in range(w):
        for g in groups([r for r in range(h) if grid[r][c]==color]):
            vgroups.append((c,g[0],g[-1]))
            for a,b in zip(g,g[1:]):
                for r in range(a+1,b):
                    if grid[r][c]==bg: out[r][c]=2
    # Join nearby perpendicular line groups with an L-shaped gap.
    for r,c1,c2 in hgroups:
        for c,r1,r2 in vgroups:
            if r < r1 and c < c1:
                dist=(c1-c)+(r1-r)
                if dist<=7:
                    for x in range(c,c1):
                        if grid[r][x]==bg: out[r][x]=2
                    for y in range(r,r1):
                        if grid[y][c]==bg: out[y][c]=2
            elif r < r1 and c > c2:
                dist=(c-c2)+(r1-r)
                if dist<=7:
                    for x in range(c2+1,c+1):
                        if grid[r][x]==bg: out[r][x]=2
                    for y in range(r,r1):
                        if grid[y][c]==bg: out[y][c]=2
            elif r > r2 and c < c1:
                dist=(c1-c)+(r-r2)
                if dist<=7:
                    for x in range(c,c1):
                        if grid[r][x]==bg: out[r][x]=2
                    for y in range(r2+1,r+1):
                        if grid[y][c]==bg: out[y][c]=2
            elif r > r2 and c > c2:
                dist=(c-c2)+(r-r2)
                if dist<=7:
                    for x in range(c2+1,c+1):
                        if grid[r][x]==bg: out[r][x]=2
                    for y in range(r2+1,r+1):
                        if grid[y][c]==bg: out[y][c]=2
    return out
'''
